/** @jsxImportSource solid-js */
import { onMount, onCleanup, createEffect } from "solid-js";
import { mountPushNavigationStack, type PushNavigationStackOptions } from "../../components/push-navigation-stack/PushNavigationStackEngine.js";
import type { MotionController } from "../../components/push-navigation-stack/motion-runtime";

export function PushNavigationStack(props: { options?: PushNavigationStackOptions; class?: string }) {
  let host!: HTMLDivElement;
  let controller: MotionController | undefined;
  onMount(() => { controller = mountPushNavigationStack(host, props.options); });
  createEffect(() => { const options = props.options; controller?.update(options ?? {}); });
  onCleanup(() => controller?.destroy());
  return <div ref={host} class={props.class} data-motion-component="push-navigation-stack" />;
}

